{"path": "units/csvfix/impl.py", "content": "import csv


def parse(line):
    """把一行 CSV 解析成 3 列的列表；每列裁剪空白。
    列数不是 3 时返回 None。引号内的逗号/转义按标准 CSV 处理。"""
    fields = next(csv.reader([line]))
    if len(fields) != 3:
        return None
    return [f.strip() for f in fields]


def total(rows):
    """每行是 [名称, 数量, 单价]，返回所有行的 数量 * 单价 之和。
    数量或单价为空白的行被跳过；非整数会抛出 ValueError。"""
    total = 0
    for row in rows:
        if len(row) < 3:
            raise ValueError("row needs 3 columns: %r" % (row,))
        qty, price = row[1].strip(), row[2].strip()
        if qty == "" or price == "":
            continue
        total += int(qty) * int(price)
    return total
"}

{"path": "units/rules/engine.py", "content": "def evaluate(rules, facts):
    """根据 facts 求值规则。支持 {"all": [...]} 与 {"any": [...]}。
    缺失的键按 False 处理；无法识别的规则返回 False。"""
    if not isinstance(rules, dict):
        return False
    if "all" in rules:
        return all(bool(facts.get(k, False)) for k in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(k, False)) for k in rules["any"])
    return False
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。
        kind 只有 "deposit" 与 "withdraw"；金额为负时抛 ValueError。"""
        for kind, account, cents in rows:
            if cents < 0:
                raise ValueError("negative amount: %r" % (cents,))
        return [row for row in rows if row[1] == op]


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    total = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
        else:
            raise ValueError("unknown kind: %r" % (kind,))
    return total
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。
    返回按起点升序的合并结果；空输入返回 []。"""
    ordered = sorted(tuple(r) for r in ranges)
    merged = []
    for lo, hi in ordered:
        if merged and lo - merged[-1][1] < minutes:
            if hi > merged[-1][1]:
                merged[-1] = (merged[-1][0], hi)
        else:
            merged.append((lo, hi))
    return merged


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    return max(a[0], b[0]) < min(a[1], b[1])
"}

{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回 [(lo, hi), ...] 升序；空输入返回 []。"""
        ordered = sorted(tuple(r) for r in ranges)
        merged = []
        for lo, hi in ordered:
            if merged and lo - merged[-1][1] - 1 <= gap:
                if hi > merged[-1][1]:
                    merged[-1] = (merged[-1][0], hi)
            else:
                merged.append((lo, hi))
        return merged

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。与 hole 不相交的段原样保留，
        被完全覆盖的段消失，横跨 hole 的段分裂成两段。"""
        hlo, hhi = hole
        result = []
        for lo, hi in self.merge(ranges):
            if hi < hlo or lo > hhi:
                result.append((lo, hi))
                continue
            if lo < hlo:
                result.append((lo, hlo - 1))
            if hi > hhi:
                result.append((hhi + 1, hi))
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}
